const calculateItemTotals = (item) => {
  const rate = parseFloat(item.rate) || 0
  const extraMarginPercentage = parseFloat(item.extraMarginPercentage) || 0
  const gstPercent = parseFloat(item.gstPercentage) || 18
  const qty = parseInt(item.qty) || 0

  // First deduct margin
  const rateWithMargin = rate * (1 - (extraMarginPercentage / 100))
  const total = qty * rateWithMargin
  // Calculate taxable value by reversing GST from total (Rate is with GST)
  const taxable = total / (1 + (gstPercent / 100))
  const gstAmount = total - taxable

  const gstType = getGstType()
  const cgst = gstType === 'cgst_sgst' ? (gstAmount / 2) : 0
  const sgst = gstType === 'cgst_sgst' ? (gstAmount / 2) : 0
  const igst = gstType === 'igst' ? gstAmount : 0

  return { rateWithMargin, taxable, cgst, sgst, igst, total }
}

